    "minimap_3s": {
      "label": "Minimap every 3 seconds",
      "short": "After each CS - look at the mini. A habit is supposed to be automatic.",
      "details": {
        "what": "Habit of looking at the minimap every 3 seconds maximum. This is NOT an option, it is the foundation of information gathering. There is no macro without it.",
        "when": "Always. The whole game. No exceptions.",
        "whenNot": "Never.",
        "success": "You know where all 5 enemies are OR you consciously don't know and predict by deduction (back 15s ago, regen 5s, move 10s - may be in X).",
        "notes": "If the mini is too far away on the monitor - reduce the HUD or move the mini. Setup matters.",
        "how": [
          "Trigger 1: every CS hit (look AFTER the last hit, in a still animation).",
          "Trigger 2: every cast fails (look PO cd when it's safe).",
          "Trigger 3: every exit from base/TP.",
          "The first 2 weeks - consciously check the clock, then the automatic one.",
          "Locked camera = fucked up. Centered rather always worse in macro."
        ],
        "mistakes": [
          "Tunnel vision on CS in 1v1.",
          "Just watching something happen (too late).",
          "Locked camera for shame that you misclick on the corners.",
          "Ignoring? on the minimap (Enemy is roaming, there will be a problem soon)."
        ]
      }
    },
    "tab_check": {
      "label": "TAB - level + items enemy",
      "short": "TAB every 30s. LEVEL + ITEMS, NOT CS/KDA. '?' = roam alert.",
      "details": {
        "what": "Checking the strength of opponents by TAB. We look at LEVEL and ITEMS (key defenses: Zhonia, Maw, Edge of Night), NOT CS/KDA - this is a myth. Plus '?' with enemy = easier to see who can roam.",
        "when": "Every 30 seconds and at every important decision (before the fight, before the objective).",
        "success": "You know who bought Zhonia → be careful with the ult combo. You know that enemy mid lvl 1 is behind you → pressure.",
        "how": [
          "TAB every ~30s or after each enemy recall.",
          "You check: ITEMS (Zhonia/Maw/Rabadon/Hex Drinker), LEVEL, summoners.",
          "'?' with enemy = think about roaming.",
          "Track jungler CS: 1 camp = 4 CS. You know what's wrong with him and where he might be.",
          "Check debuffs (ADC heals), Ekko clones (has/does not have an ult)."
        ],
        "mistakes": [
          "Looking at KDA (non-informative).",
          "Watching once per game.",
          "No jungler CS counting (you lose key info)."
        ]
      }
    },
    "fog_tracking": {
      "label": "Fog of war - position deduction",
      "short": "Reverse = ~10s free + regen. Imagine your range growing every second.",
      "details": {
        "what": "When the enemy disappears from the map, you track it by deduction. You imagine the 'range' increasing every second. It gives you an idea of ​​where it COULD be with probability.",
        "when": "All the time. Every decision requires 'where are all the enemies'.",
        "success": "Your prediction is 70%+ correct - enemies appear where you expected.",
        "how": [
          "Enemy moved back to the base → add mana/HP regen seconds (~5s) + arrival time.",
          "Enemy disappears on the river → 2 options: retreats / goes somewhere. You can imagine both ranges.",
          "Follow jg by CS - 1 camp = 4 CS. You know where he was (invade?) and what gets up.",
          "Deduction: 'A is empty, I am in B, so the enemy is in C'.",
          "The more players you see = the fewer opportunities for the unseen."
        ],
        "mistakes": [
          "The assumption 'he rolled back so he's been gone for 5 minutes'.",
          "No regen time counting.",
          "Ignoring the 'support not visible for 30s' information."
        ]
      }
    },
    "mute_all": {
      "label": "Communication: Pings YES, Chat NO",
      "short": "All chat OFF. Only pings (numbers, summy, danger).",
      "details": {
        "what": "Communication in soloQ gives 90% of the emotional cost, 10% of the value. Pings transmit information without emotions. Chat = 99% contributes nothing and is distracting.",
        "when": "Every game. No exceptions.",
        "success": "After the game, you don't remember emotions about the team - you only remember your actions.",
        "how": [
          "All chat OFF to 100% in settings.",
          "Team chat - mute immediately if someone barks.",
          "Only pings: missing, danger, on my way, smite up.",
          "Chat numbers for flashy enemy: 1=top, 2=jg, 3=mid, 4=adc, 5=sup.",
          "Mental rule: you don't comment on the team even in your head."
        ],
        "mistakes": [
          "Replying even when you're right.",
          "Pinging out of frustration instead of information.",
          "Reading all chata 'because maybe there's something interesting'."
        ]
      }
    },
